onCheckedChange: {async (v) => {
                      const next = !!v;

                      // Optimistic UI
                      setRows((prev) =>
                        prev.map((x) =>
                          x.id === r.id ? { ...x, isAvailable: next } : x,
                        ),
                      );

                      try {
                        await apiRequest(
                          "PATCH",
                          buildUrl(api.plans.resourceItems.update.path, {
                            id: planId,
                            itemId: r.id,
                          }),
                          { isAvailable: next },
                        );
                      } catch (e: any) {
                        alert(friendlyError(e) || "No se pudo guardar");
                        await load();
                        onChanged?.();
                      }
                    }}

