                        const name = e.currentTarget.value.trim();
                        if (!name || name === r.name) return;

                        try {
                          await apiRequest(
                            "PATCH",
                            buildUrl(api.plans.resourceItems.update.path, {
                              id: planId,
                              itemId: r.id,
                            }),
                            { name },
                          );

                          setRows((prev) =>
                            prev.map((x) =>
                              x.id === r.id ? { ...x, name } : x,
                            ),
                          );
                          onChanged?.();
                        } catch (err: any) {
                          alert(friendlyError(err) || "No se pudo renombrar");
                          await load();
                          onChanged?.();
